// Department Master
// 1 Department ID (auto: prefix + FY + running no) | 2 Code | 3 Name | 4 Description | 5 Type | 6 Parent
// 7 Scope | 8 Status | 9 Display Order | 10 Created By | 11 Created At | 12 Updated By / At
export interface Department {
  id: string; // internal database id (not shown to users)
  // Department ID shown to users, e.g. DEP/25-26/0001
  // = prefix (Settings > Prefix) + financial year + running number.
  // Generated by the backend on create, never typed in the form.
  departmentNo: string;
  code: string;
  name: string;
  description: string;
  typeId: string;
  typeName: string;
  parentId: string;
  parentName: string;
  scope: string;
  status: string; // "Active" | "Inactive"
  displayOrder: string; // kept as string for the input, converted on save
  createdBy: string; // system
  createdAt: string; // system
  updatedBy: string; // system
  updatedAt: string; // system
}

export const emptyDepartment = (): Department => ({
  id: "",
  departmentNo: "",
  code: "",
  name: "",
  description: "",
  typeId: "",
  typeName: "",
  parentId: "",
  parentName: "",
  scope: "",
  status: "Active",
  displayOrder: "",
  createdBy: "",
  createdAt: "",
  updatedBy: "",
  updatedAt: "",
});

// ---- Map backend response to frontend Department shape ----
// TODO: match these field names with your backend response.
export function mapApiDepartmentToDepartment(api: any): Department {
  return {
    id: String(api.departmentId ?? api.id ?? ""),

    departmentNo: api.departmentNo ?? "",

    code: api.departmentCode ?? "",

    name: api.departmentName ?? "",

    description: api.description ?? "",

    typeId: api.departmentTypeId ? String(api.departmentTypeId) : "",

    // Backend currently sends typeName
    typeName: api.typeName ?? api.departmentTypeName ?? "",

    parentId: api.parentDepartmentId ? String(api.parentDepartmentId) : "",

    parentName: api.departmentParentName ?? api.parentDepartmentName ?? "",

    scope: api.scope ?? "",

    status: api.status ?? "Active",

    displayOrder:
      api.displayOrder === null || api.displayOrder === undefined
        ? ""
        : String(api.displayOrder),

    createdBy: api.createdBy ? String(api.createdBy) : "",

    createdAt: api.created ?? api.createdAt ?? "",

    updatedBy: api.updatedBy ? String(api.updatedBy) : "",

    updatedAt: api.updated ?? api.updatedAt ?? "",
  };
}

export const formatDateTime = (value: string) => {
  if (!value) return "—";
  const d = new Date(value);
  return isNaN(d.getTime()) ? value : d.toLocaleString();
};
